import { Suspense } from "react";

function Seite({ kopfPromise, listePromise, empfehlungenPromise }) {
  return (
    <main>
      <Kopf datenPromise={kopfPromise} />
      <Suspense fallback={<p>Liste laedt ...</p>}>
        <Liste datenPromise={listePromise} />
      </Suspense>
      <Suspense fallback={<p>Empfehlungen laden ...</p>}>
        <Empfehlungen datenPromise={empfehlungenPromise} />
      </Suspense>
    </main>
  );
}
